# Find connected components (4-connectivity)
visited = set()
components = []

def get_component(i, j, grid, rows, cols):
    comp = []
    stack = [(i, j)]
    while stack:
        ci, cj = stack.pop()
        if (ci, cj) in visited:
            continue
        visited.add((ci, cj))
        comp.append((ci, cj))

        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = ci + di, cj + dj
            if 0 <= ni < rows and 0 <= nj < cols:
                if grid[ni][nj] == grid[ci][cj]:
                    if (ni, nj) not in visited:
                        stack.append((ni, nj))
    return comp

for i in range(10):
    for j in range(10):
        if demo1_left_input[i][j] == 4 and (i, j) not in visited:
            comp = get_component(i, j, demo1_left_input, 10, 10)
            labels = {p: len(components) for p in comp}
            components.append(labels)

# Map each 4 to its component ID
